CREATE TABLE groups (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE group_members (group_id TEXT REFERENCES groups(id) ON DELETE CASCADE, bot_id TEXT REFERENCES bots(id) ON DELETE CASCADE, PRIMARY KEY(group_id,bot_id));
CREATE TABLE group_messages (id TEXT PRIMARY KEY, group_id TEXT REFERENCES groups(id) ON DELETE CASCADE, actor_id TEXT NOT NULL, bot_id TEXT, content TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE handoffs (id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES groups(id) ON DELETE CASCADE, request_id TEXT NOT NULL, principal_id TEXT NOT NULL, source_bot_id TEXT, source_run_id TEXT, target_bot_id TEXT NOT NULL REFERENCES bots(id) ON DELETE CASCADE, target_run_id TEXT, task TEXT NOT NULL, context TEXT NOT NULL, correlation_id TEXT NOT NULL, hop INTEGER NOT NULL, budget INTEGER NOT NULL, deadline TEXT NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL, detail TEXT, UNIQUE(group_id,request_id,target_bot_id), UNIQUE(correlation_id,target_bot_id));
